public class PathRouterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String handlerOf(RouteMatch m) {
        return m == null ? "no match" : m.handler();
    }

    static String paramOf(RouteMatch m, String key) {
        return m == null ? "no match" : String.valueOf(m.params().get(key));
    }

    static int paramCount(RouteMatch m) {
        return m == null ? -1 : m.params().size();
    }

    public static void main(String[] args) {
        try {
            PathRouter router = new PathRouter();
            router.add("/health", "healthCheck");
            router.add("/users/{id}", "showUser");
            router.add("/users/me", "currentUser");
            router.add("/users/{id}/posts/{postId}", "showPost");

            check("a literal route", "healthCheck", handlerOf(router.match("/health")));
            check("a literal route has no parameters", 0, paramCount(router.match("/health")));

            RouteMatch user = router.match("/users/42");
            check("a placeholder route", "showUser", handlerOf(user));
            check("the placeholder value is captured", "42", paramOf(user, "id"));

            check("one trailing slash is ignored", "showUser",
                    handlerOf(router.match("/users/42/")));

            RouteMatch post = router.match("/users/7/posts/99");
            check("two placeholders", "showPost", handlerOf(post));
            check("first placeholder", "7", paramOf(post, "id"));
            check("second placeholder", "99", paramOf(post, "postId"));
            check("two parameters captured", 2, paramCount(post));

            check("too few segments do not match", "no match", handlerOf(router.match("/users")));
            check("a different literal does not match", "no match",
                    handlerOf(router.match("/orders/42")));
            check("matching is case sensitive", "no match", handlerOf(router.match("/Health")));

            check("first registered route wins a tie", "showUser",
                    handlerOf(router.match("/users/me")));
            check("and it captures the value as a parameter", "me",
                    paramOf(router.match("/users/me"), "id"));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

