import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Provided -- do not edit. The result of a successful route match. */
record RouteMatch(String handler, Map<String, String> params) {
}

/**
 * TASK: Build the routing table a small web framework uses.
 *
 * add(pattern, handler) registers a route. A pattern is a path whose segments
 * are either literal text or a placeholder written as {name}:
 *     "/users"              "/users/{id}"       "/users/{id}/posts/{postId}"
 *
 * match(path) returns a RouteMatch for the FIRST registered pattern that fits,
 * or null when nothing fits. A pattern fits when it has the same number of
 * segments and every literal segment is exactly equal (case sensitive); each
 * {name} segment matches any NON-EMPTY segment and records it as a parameter.
 *
 *   add("/users/{id}", "showUser"); match("/users/42")
 *       -> handler "showUser", params {id=42}
 *   match("/users/42/")   -> the same: one trailing slash is ignored
 *   match("/users")       -> null (wrong number of segments)
 *   match("/orders/42")   -> null (the literal segment differs)
 *
 * TRICKY EDGE: registration order decides ties. If "/users/{id}" is added
 * before "/users/me", then match("/users/me") returns the {id} route with
 * params {id=me} -- first match wins, not most specific.
 */
public class PathRouter {

    private final List<String> patterns = new ArrayList<>();
    private final List<String> handlers = new ArrayList<>();

    public void add(String pattern, String handler) {
        patterns.add(pattern);
        handlers.add(handler);
    }

    private static String[] segments(String path) {
        String trimmed = path;
        while (trimmed.endsWith("/") && trimmed.length() > 1) {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }
        return trimmed.split("/", -1);
    }

    public RouteMatch match(String path) {
        if (path == null) {
            return null;
        }
        String[] actual = segments(path);
        for (int i = 0; i < patterns.size(); i++) {
            String[] expected = segments(patterns.get(i));
            if (expected.length != actual.length) {
                continue;
            }
            Map<String, String> params = new LinkedHashMap<>();
            boolean fits = true;
            for (int s = 0; s < expected.length; s++) {
                String want = expected[s];
                String have = actual[s];
                if (want.startsWith("{") && want.endsWith("}") && want.length() > 2) {
                    if (have.isEmpty()) {
                        fits = false;
                        break;
                    }
                    params.put(want.substring(1, want.length() - 1), have);
                } else if (!want.equals(have)) {
                    fits = false;
                    break;
                }
            }
            if (fits) {
                return new RouteMatch(handlers.get(i), params);
            }
        }
        return null;
    }
}
